{
  "headline": "Argatroban is not on FDA's shortage list; our supply traces to a plant classified OAI 259 days before the latest inspection posting",
  "headline_cites": ["D4", "E11", "E13"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include argatroban as of 2026-10-21.",
      "cites": ["D4"]
    },
    {
      "text": "Both Corvale East and Corvale General stock argatroban 50 mg/50 mL vials labeled by Eugia US LLC with NDC 55150024101.",
      "cites": ["E1", "E3"]
    },
    {
      "text": "The product label identifies the manufacturing plant as Eugia Pharma Specialities Limited (FEI 3008461619) in India.",
      "cites": ["E13"]
    },
    {
      "text": "FDA inspected that plant on 2026-02-06 and classified it OAI; the classification was posted on 2026-09-21.",
      "cites": ["E11"]
    },
    {
      "text": "An earlier OAI inspection ended 2024-02-02 with a Warning Letter issued 2024-08-15.",
      "cites": ["E9", "E12"]
    },
    {
      "text": "The ranked transfer option moves 23 vials from Corvale General (16.5 days on hand) to Corvale East (8.2 days on hand), leaving the sender with 14 days and the receiver with 11 days.",
      "cites": ["D5"]
    },
    {
      "text": "Alternate manufacturers Accord Healthcare Inc. and Amneal Pharmaceuticals LLC are not on the shortage list, but their labels name no plant we could place.",
      "cites": ["D6", "D7"]
    }
  ]
}
